static void testPlaylistLoopRanges(const File& root,Assets& assets){
    auto source=demoProject();auto original=JSON::toString(projectToJson(source));Project out;expect(setPlaylistLoopRange(source,4,8,out).wasOk()&&out.songMode&&out.loop&&out.loopSection==playlistLoopMarkerId,"Playlist range enables Song looping through an ordinary saved section");
    auto* range=findSongMarker(out,playlistLoopMarkerId);expect(range&&range->beat==4&&range->endBeat==8&&out.clips.size()==source.clips.size()&&out.patterns[0].lanes==source.patterns[0].lanes&&JSON::toString(projectToJson(source))==original,"loop range leaves source arrangement and musical data intact");
    auto compiled=std::make_unique<Playback>();auto& state=*compiled;String warnings;expect(compilePlayback(out,assets,root,state,warnings).wasOk()&&state.loop&&state.loopStart==4&&state.loopEnd==8&&state.trackCount==(int)source.tracks.size(),"loop range compiles full arrangement and all channels between chosen boundaries");
    Project restored;expect(projectFromJson(projectToJson(out),restored).wasOk()&&restored.loopSection==playlistLoopMarkerId&&findSongMarker(restored,playlistLoopMarkerId)->endBeat==8,"Playlist range persists with schema15 and existing section semantics");
    expect(setPlaylistLoopRange(out,8,12,restored).wasOk()&&restored.markers.size()==out.markers.size(),"choosing a new Playlist range reuses its section instead of accumulating markers");
    Project sentinel=emptyProject();auto token=JSON::toString(projectToJson(sentinel));for(auto bounds:std::vector<std::pair<double,double>>{{-1,4},{4,4},{4,4.1},{4,3},{4095,4097},{std::nan(""),8},{0,std::nan("")}})expect(setPlaylistLoopRange(source,bounds.first,bounds.second,sentinel).failed()&&JSON::toString(projectToJson(sentinel))==token,"invalid loop bounds preserve the entire destination");
    auto full=source;full.markers.clear();full.loopSection.clear();for(int i=0;i<maxSongMarkers;++i)full.markers.push_back({"m"+String(i),"Existing marker",(double)i,-1,0});expect(setPlaylistLoopRange(full,0,4,sentinel).failed()&&full.markers.size()==maxSongMarkers,"loop creation at marker capacity rejects without deleting user markers");full.markers.back()={playlistLoopMarkerId,"Playlist loop",0,4,4};expect(setPlaylistLoopRange(full,4,8,out).wasOk()&&out.markers.size()==maxSongMarkers,"an existing Playlist loop updates at marker capacity");
    auto named=source;storeSongMarker(named,{"verse","Verse",4,8,1});named.loopSection="verse";expect(clearPlaylistLoopRange(named,out).wasOk()&&!out.loop&&out.loopSection.isEmpty()&&findSongMarker(out,"verse"),"clearing a named loop preserves its song section");setPlaylistLoopRange(named,8,12,out);expect(clearPlaylistLoopRange(out,restored).wasOk()&&!restored.loop&&!findSongMarker(restored,playlistLoopMarkerId)&&findSongMarker(restored,"verse"),"clearing Playlist range removes only its own temporary section");
    std::set<uint32_t> colours;for(int i=0;i<maxPatterns;++i)colours.insert(automaticPatternColourARGB(i));expect(colours.size()==maxPatterns&&automaticPatternColourARGB(0)==patternColourARGB(1),"all32 Automatic pattern swatches are distinct and the first retains familiar green");
}
